  constructor(src) {
    this.chars = Array.from(src)
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.pos >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  mark() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.chars[this.pos]
    this.pos++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return c
  }

  slice(startPos, endPos) {
    return this.chars.slice(startPos, endPos).join('')
  }
}

/** A scanning failure carrying the source position of its cause. */
