  const start = sc.mark()
  const startPos = sc.pos
  sc.advance()
  while (isIdentPart(sc.peek())) sc.advance()
  const text = sc.slice(startPos, sc.pos)
  return { line: start.line, col: start.col, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text }
