    if (marker === 'x' || marker === 'X') isDigitFn = isHexDigit
    else if (marker === 'b' || marker === 'B') isDigitFn = (c) => c === '0' || c === '1'
    else isDigitFn = (c) => c !== undefined && /[0-7]/.test(c)
