      const start = sc.mark()
      for (let i = 0; i < p.length; i++) sc.advance()
      tokens.push({ line: start.line, col: start.col, kind: 'punct', text: p })
      continue
    }
    const start = sc.mark()
    throw new LexError(start.line, start.col, `unexpected character ${c}`)
  }
  return tokens
